import { disabled, fieldSurface, focusRing } from "@/lib/beton/shared";
import { tv, type VariantProps } from "@/lib/beton/tv";

export const textarea = tv({
  base: [
    "block w-full min-w-0 resize-y",
    fieldSurface,
    "read-only:shadow-none",
    focusRing,
    disabled,
  ],
  variants: {
    size: {
      sm: "min-h-24 px-2.5 py-2 text-sm",
      md: "min-h-28 px-3 py-2.5 text-base",
      lg: "min-h-36 px-4 py-3 text-lg",
    },
  },
  defaultVariants: {
    size: "md",
  },
});

export type TextareaVariants = VariantProps<typeof textarea>;

"use client";

import { Field } from "@base-ui/react/field";
import { textarea, type TextareaVariants } from "@/lib/beton/recipes/textarea.recipe";
import type { ComponentProps } from "react";

export interface TextareaProps
  extends Omit<ComponentProps<"textarea">, "className" | "defaultValue">, TextareaVariants {
  className?: string;
  defaultValue?: string;
}

/** A multi-line text field. Inside `Field`, it is labelled and validated automatically. */
export function Textarea({ size = "md", className, ...props }: TextareaProps) {
  return (
    <Field.Control
      {...(props as Field.Control.Props)}
      render={<textarea />}
      data-size={size}
      className={textarea({ size, class: className })}
    />
  );
}
